select     round(zzsyje / 100000000, 2) as zzsyje,     round(case when qn_zzsyje = 0 then 0 else zzsyje / qn_zzsyje end * 100, 2) as zzsytbzzl,     round((qn_zzsyje - zzsyje) / 10000, 2) as zzsyjsje,     round(ywsrje / 100000000, 2) as ywsrje,     round(case when qn_ywsrje = 0 then 0 else ywsrje / qn_ywsrje end * 100, 2) as ywsrtbzzl,     round(ywzcje / 100000000, 2) as ywzcje,     round(case when qn_ywzcje = 0 then 0 else ywzcje / qn_ywzcje end * 100, 2) as ywzctbzzl from (     select         sum(jn.dyzzsr) zzsyje,         sum(qn.dyzzsr) qn_zzsyje,         (sum(jn.dyzfgjjlxsr) + sum(jn.dyzzsylxsr) + sum(jn.dywtdklxsr) + sum(jn.dygjzqlxsr) + sum(jn.dyqtsr)) as ywsrje,         (sum(qn.dyzfgjjlxsr) + sum(qn.dyzzsylxsr) + sum(qn.dywtdklxsr) + sum(qn.dygjzqlxsr) + sum(qn.dyqtsr)) as qn_ywsrje,         (sum(jn.dyzfgjjlxzc) + sum(jn.dyzfgjjgjsxfzc) + sum(jn.dywtdksxfzc) + sum(jn.dyqtzc)) as ywzcje,         (sum(qn.dyzfgjjlxzc) + sum(qn.dyzfgjjgjsxfzc) + sum(qn.dywtdksxfzc) + sum(qn.dyqtzc)) as qn_ywzcje     from         (             select * from dws_fin_bal_mem where             LEFT(tjzq, 4) = #{ssnd}             AND CASE #{ssjd}                 WHEN 1 THEN SUBSTRING(tjzq, 5, 2) IN ('01', '02', '03')                 WHEN 2 THEN SUBSTRING(tjzq, 5, 2) IN ('04', '05', '06')                 WHEN 3 THEN SUBSTRING(tjzq, 5, 2) IN ('07', '08', '09')                 WHEN 4 THEN SUBSTRING(tjzq, 5, 2) IN ('10', '11', '12')             end         ) as jn,         (             select * from dws_fin_bal_mem where             LEFT(tjzq, 4) = #{ssnd}             AND CASE #{ssjd}                 WHEN 1 THEN SUBSTRING(tjzq, 5, 2) IN ('01', '02', '03')                 WHEN 2 THEN SUBSTRING(tjzq, 5, 2) IN ('04', '05', '06')                 WHEN 3 THEN SUBSTRING(tjzq, 5, 2) IN ('07', '08', '09')                 WHEN 4 THEN SUBSTRING(tjzq, 5, 2) IN ('10', '11', '12')             end         ) as qn ) as t 
